-- Durable mock financial requests, explicit checkout actions and immutable verified funds.
-- Native 001--109 remain unchanged; no real funds or public deployment.

CREATE TABLE _dg_native_bill_operation_revisions(operation_id text NOT NULL REFERENCES restaurant_financial_operations(id),version bigint NOT NULL,action_id text NOT NULL REFERENCES _dg_native_dining_actions(id),row_hash text NOT NULL,created_at text NOT NULL,PRIMARY KEY(operation_id,version));
CREATE TABLE _dg_native_bill_receipt_revisions(event_id text NOT NULL REFERENCES restaurant_financial_receipts(event_id),revision bigint NOT NULL,action_id text NOT NULL REFERENCES _dg_native_dining_actions(id),row_hash text NOT NULL,created_at text NOT NULL,PRIMARY KEY(event_id,revision));
CREATE TABLE _dg_native_bill_mock_fixture_origins(operation_id text PRIMARY KEY REFERENCES restaurant_financial_operations(id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),sequence bigint NOT NULL,created_at text NOT NULL);
DO $bill_transport_immutable$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['_dg_native_bill_operation_revisions','_dg_native_bill_receipt_revisions','_dg_native_bill_mock_fixture_origins'] LOOP EXECUTE format('CREATE TRIGGER native_bill_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_append_only()',table_value);END LOOP;END;$bill_transport_immutable$;
INSERT INTO _dg_native_bill_operation_revisions SELECT operation.id,operation.version,actual_action.id,dg_native_office_hash(to_jsonb(operation)),operation.updated_at FROM restaurant_financial_operations operation JOIN _dg_native_bill_operation_origins origin ON origin.operation_id=operation.id CROSS JOIN LATERAL(SELECT actual.* FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name='restaurant_financial_operations' AND effect.resource_id=operation.id AND actual.created_at=operation.updated_at ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1) actual_action;

CREATE FUNCTION dg_native_bill_transport_lock(target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;r restaurants%ROWTYPE;
BEGIN
 SELECT bill.* INTO b FROM restaurant_financial_operations operation JOIN _dg_native_bill_operation_origins origin ON origin.operation_id=operation.id JOIN restaurant_bills bill ON bill.id=operation.bill_id WHERE operation.id=target;IF b.id IS NULL THEN PERFORM dg_native_bill_error('NOT_FOUND');END IF;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;
 PERFORM pg_advisory_xact_lock(hashtextextended('["native-asset-workspace",'||to_jsonb(r.tenant_id)::text||','||to_jsonb(r.workspace_id)::text||']',0));PERFORM id FROM restaurants WHERE id=r.id FOR UPDATE;PERFORM id FROM dining_parties WHERE id=b.party_id FOR UPDATE;PERFORM id FROM restaurant_orders WHERE id=b.order_id FOR UPDATE;PERFORM id FROM restaurant_bills WHERE id=b.id FOR UPDATE;PERFORM id FROM restaurant_financial_operations WHERE id=target FOR UPDATE;
END;$dg$;

CREATE FUNCTION dg_native_bill_transport_action(target text,kind_value text,input jsonb DEFAULT '{}') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;
BEGIN
 SELECT jsonb_build_object('restaurantId',r.id,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'partyId',b.party_id,'partyAccessVersion',p.access_version,'actorType','worker','actorId','native-financial-worker','actorEpoch',NULL,'grantVersion',NULL,'sessionId',NULL,'accessId',NULL,'focusVersion',NULL,'selectionVersion',NULL) INTO meta FROM restaurant_financial_operations operation JOIN restaurant_bills b ON b.id=operation.bill_id JOIN restaurants r ON r.id=b.restaurant_id JOIN dining_parties p ON p.id=b.party_id WHERE operation.id=target;
 RETURN dg_native_dining_action(meta,kind_value,'party',meta->>'partyId',input);
END;$dg$;

CREATE FUNCTION dg_native_bill_action_reason(target text,mode_value text,meta jsonb,attempted_value boolean DEFAULT false) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;p dining_parties%ROWTYPE;config restaurant_payment_configs%ROWTYPE;t jsonb;
BEGIN
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;SELECT * INTO p FROM dining_parties WHERE id=b.party_id;SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=b.restaurant_id;t:=dg_native_bill_totals(b.id);
 IF mode_value='query' THEN RETURN NULL;END IF;
 IF meta->>'actorType'='staff' THEN IF NOT dg_native_dining_clock_authority(meta->>'actorId',b.restaurant_id,(meta->>'actorEpoch')::bigint,(meta->>'grantVersion')::bigint) THEN RETURN '原人员职责已经变化。';END IF;
 ELSIF NOT dg_native_order_source(meta,p.id) THEN RETURN '本次会话、发问人、选择或就餐归属已经变化。';END IF;
 IF p.access_version IS DISTINCT FROM(meta->>'partyAccessVersion')::bigint THEN RETURN '原就餐归属已经变化。';END IF;
 IF operation.kind<>'payment' OR operation.send_attempts<>1 OR operation.status NOT IN('pending','unknown') OR operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED' OR EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=operation.id) THEN RETURN '原请求不允许执行新的付款或关闭动作，请查询原结果。';END IF;
 IF mode_value='simulate' THEN
  IF operation.status<>'pending' OR operation.remote_operation_id IS NULL OR operation.simulate_attempts<>(CASE WHEN attempted_value THEN 1 ELSE 0 END) OR(t->>'balance')::bigint<operation.amount_minor OR dg_native_bill_payment_reason(b.order_id,meta) IS NOT NULL OR(SELECT content_version FROM restaurant_orders WHERE id=b.order_id)<>b.order_content_version THEN RETURN '本次入口、金额、接单明细或模拟付款次数已变化，请查询原请求。';END IF;
  IF config.restaurant_id IS NULL OR config.enabled<>1 OR config.provider_id<>operation.provider_id OR config.version<>operation.config_version OR config.merchant_id<>operation.merchant_id THEN RETURN '原支付连接或商户已经变化，未执行模拟付款。';END IF;
 END IF;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_bill_action(target text,input jsonb,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;body jsonb:=input-ARRAY['focusVersion','selectionVersion'];operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;action_value text;created text;mode_value text:=body->>'action';
BEGIN
 IF mode_value='withdraw' THEN RETURN dg_native_bill_apply('operation',target,'withdraw',input,session_value,token_value,csrf_value,focus_value);END IF;
 meta:=dg_native_bill_context('operation',target,session_value,token_value,csrf_value,focus_value,true,true);PERFORM dg_native_order_input(meta,input);PERFORM dg_native_restaurant_fields(body,ARRAY['version','action','confirmed']);
 IF mode_value IS NULL OR mode_value NOT IN('query','close','simulate') OR body->'confirmed' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target FOR UPDATE;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;IF dg_native_restaurant_integer(body->'version',1,9007199254740991)<>operation.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
 IF operation.kind='refund' AND mode_value<>'query' AND NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;
 IF operation.send_attempts<>1 OR operation.status NOT IN('pending','unknown','needs_attention') OR operation.lease_token IS NOT NULL AND(operation.lease_until>dg_native_dining_now() OR mode_value<>'query') OR operation.next_action IS NOT NULL OR dg_native_bill_action_reason(operation.id,mode_value,meta) IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_ACTION_UNAVAILABLE');END IF;
 action_value:=dg_native_dining_action(meta,'bill_action','party',b.party_id,body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 INSERT INTO _dg_native_bill_action_origins VALUES(action_value,operation.id,mode_value,meta,created);PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET next_action=mode_value,action_actor_id=meta->>'actorId',action_session_id=meta->>'sessionId',action_focus_version=(meta->>'focusVersion')::bigint,action_party_access_version=(meta->>'partyAccessVersion')::bigint,version=version+1,updated_at=created WHERE id=operation.id;
 PERFORM dg_native_bill_refresh(action_value,b.id);PERFORM dg_native_bill_event(action_value,b.id,operation.id,'已明确请求核对原资金操作；未知结果保留原编号，不重新发送付款或退款。');INSERT INTO _dg_native_bill_results VALUES(action_value,b.restaurant_id,b.id,(meta->>'partyAccessVersion')::bigint,created);RETURN action_value;
END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_bill_refresh(action_value text,target text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;state_value jsonb;created text;
BEGIN
 SELECT * INTO b FROM restaurant_bills WHERE id=target;state_value:=dg_native_bill_state(b.id);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_bills',b.id);UPDATE restaurant_bills SET status=state_value->>'status',attention_reason=state_value->>'attentionReason',settled_at=CASE WHEN settled_at IS NULL AND(state_value->>'settled')::boolean THEN created ELSE settled_at END,version=version+1,updated_at=created WHERE id=b.id;
 SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;
 IF(state_value->>'settled')::boolean AND(o.settlement_status<>'settled' OR dg_native_bill_order_fulfilled(o.id) AND o.status NOT IN('closed','cancelled')) THEN PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET settlement_status='settled',status=CASE WHEN dg_native_bill_order_fulfilled(id) AND status<>'cancelled' THEN 'closed' ELSE dg_native_order_status(id) END,version=version+1,updated_at=created WHERE id=o.id;END IF;
END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_bill_order_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE actual_action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF table_value<>'restaurant_orders' THEN RETURN false;END IF;
 SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=j->>'id' AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id AND actual.restaurant_id=j->>'restaurant_id' AND actual.resource_id=j->>'party_id' AND actual.kind IN('bill_review','bill_receipt','order_receipt') ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;IF actual_action.id IS NULL THEN RETURN false;END IF;
 IF actual_action.kind='order_receipt' AND(j->>'settlement_status'<>'settled' OR j-ARRAY['settlement_status','status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['settlement_status','status','version','updated_at']) THEN RETURN false;END IF;
 IF operation_value<>'UPDATE' OR previous->>'settlement_status' NOT IN('unsettled','settled') OR j->>'settlement_status'<>'settled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['settlement_status','status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['settlement_status','status','version','updated_at'] OR j->>'updated_at'<>actual_action.created_at OR NOT EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.order_id=j->>'id' AND bill.status IN('paid','partially_refunded','refunded','void') AND bill.attention_reason IS NULL AND bill.order_content_version=(j->>'content_version')::bigint) OR j->>'status' IS DISTINCT FROM(CASE WHEN previous->>'status'='cancelled' THEN 'cancelled' WHEN dg_native_bill_order_fulfilled(j->>'id') THEN 'closed' ELSE dg_native_order_status(j->>'id') END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order settlement requires actual verified bill facts and independently complete kitchen fulfillment';END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_bill_order_changed(action_value text,order_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE bill_value text;
BEGIN SELECT bill_id INTO bill_value FROM _dg_native_bill_origins WHERE order_id=order_value;IF bill_value IS NOT NULL THEN PERFORM dg_native_bill_refresh(action_value,bill_value);END IF;END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_bill_operation_project(target text,meta jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;manager_value boolean;active boolean;busy boolean;auto_value boolean;
BEGIN
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;manager_value:=dg_native_bill_manager(meta);active:=operation.status IN('pending','unknown','needs_attention') AND operation.send_attempts=1;busy:=operation.lease_token IS NOT NULL AND operation.lease_until>dg_native_dining_now() OR operation.next_action IS NOT NULL;auto_value:=meta->>'actorType'='staff' OR dg_native_order_source(meta,meta->>'partyId');
 RETURN jsonb_build_object('id',operation.id,'billId',operation.bill_id,'kind',operation.kind,'parentPaymentId',operation.parent_payment_id,'status',operation.status,'version',operation.version,'amountMinor',operation.amount_minor,'currency','CNY','reason',CASE WHEN operation.kind='refund' AND NOT manager_value THEN '门店经理核对退款' ELSE operation.reason END,'simulated',operation.simulated=1,'sendAttempts',operation.send_attempts,'simulateAttempts',operation.simulate_attempts,'lookups',operation.lookups,'nextAction',operation.next_action,'checkoutReady',operation.kind='payment' AND operation.status='pending' AND operation.remote_operation_id IS NOT NULL,'canSimulate',auto_value AND NOT busy AND operation.lease_token IS NULL AND dg_native_bill_action_reason(operation.id,'simulate',meta) IS NULL,'canQuery',active AND NOT busy AND auto_value,'canClose',active AND NOT busy AND operation.lease_token IS NULL AND auto_value AND dg_native_bill_action_reason(operation.id,'close',meta) IS NULL,'canWithdraw',operation.status='queued' AND operation.send_attempts=0 AND operation.lease_token IS NULL AND(operation.kind='payment' OR manager_value) AND auto_value,'refundableMinor',CASE WHEN operation.kind='payment' THEN coalesce(dg_native_bill_refundable(operation.id),0) ELSE 0 END,'remoteOperationId',operation.remote_operation_id,'remoteTransactionId',operation.remote_transaction_id,'errorMessage',operation.error_message,'createdAt',operation.created_at,'updatedAt',operation.updated_at);
END;$dg$;

ALTER TABLE _dg_native_bill_worker_leases ADD COLUMN source_action_id text REFERENCES _dg_native_bill_action_origins(action_id);

CREATE FUNCTION dg_native_bill_worker_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE candidate record;operation restaurant_financial_operations%ROWTYPE;action_value text;created text;mode_value text;reason_value text;lease_value text;expires text;source_action _dg_native_bill_action_origins%ROWTYPE;interrupted boolean;
BEGIN
 PERFORM dg_native_reception_runtime(true);
 FOR candidate IN SELECT financial.id FROM restaurant_financial_operations financial JOIN _dg_native_bill_operation_origins origin ON origin.operation_id=financial.id WHERE financial.status='queued' AND financial.send_attempts=0 OR financial.status IN('submitting','pending','unknown','needs_attention') AND(financial.lease_token IS NOT NULL AND financial.lease_until<=dg_native_dining_now() OR financial.lease_token IS NULL AND(financial.next_action IS NOT NULL OR financial.kind='refund' AND financial.status='pending' AND financial.lookups<3 AND(financial.last_lookup_at IS NULL OR financial.last_lookup_at<=dg_native_people_iso(clock_timestamp()-interval '1 second')))) ORDER BY financial.created_at,financial.id LIMIT 25 LOOP
  PERFORM dg_native_bill_transport_lock(candidate.id);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=candidate.id;IF operation.lease_token IS NOT NULL AND operation.lease_until>dg_native_dining_now() OR operation.status IN('succeeded','failed','expired','cancelled','stale') THEN CONTINUE;END IF;
  interrupted:=operation.lease_token IS NOT NULL;source_action:=NULL;
  IF operation.status='queued' AND operation.send_attempts=0 THEN
   reason_value:=dg_native_bill_quote_reason(operation.quote_id,NULL,true);IF reason_value IS NOT NULL THEN
    action_value:=dg_native_bill_transport_action(operation.id,'bill_stale');SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='stale',error_code='FINANCIAL_SOURCE_CHANGED',error_message='原审阅期限、人员授权、会话、金额或连接已变化，未发送请求已停止，请重新核对。',version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_value,operation.bill_id);PERFORM dg_native_bill_event(action_value,operation.bill_id,operation.id,'发送前原来源失效，未发送资金请求已停止。');CONTINUE;
   END IF;mode_value:='send';
  ELSIF operation.send_attempts=1 AND operation.status IN('submitting','pending','unknown','needs_attention') THEN
   mode_value:=CASE WHEN interrupted THEN 'query' ELSE coalesce(operation.next_action,'query') END;
   IF NOT interrupted AND operation.next_action IS NOT NULL THEN SELECT * INTO source_action FROM _dg_native_bill_action_origins WHERE operation_id=operation.id AND mode=mode_value ORDER BY created_at DESC,action_id DESC LIMIT 1;END IF;
   IF mode_value IN('close','simulate') THEN
    reason_value:=CASE WHEN source_action.action_id IS NULL THEN '缺少原明确动作。' ELSE dg_native_bill_action_reason(operation.id,mode_value,source_action.actor_meta) END;
    IF reason_value IS NOT NULL THEN action_value:=dg_native_bill_transport_action(operation.id,'bill_action_blocked');SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET next_action=NULL,error_code='FINANCIAL_ACTION_BLOCKED',error_message='原明确动作的权限、会话、连接或金额已变化，未执行新的付款或关闭，请核对原结果。',version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_value,operation.bill_id);PERFORM dg_native_bill_event(action_value,operation.bill_id,operation.id,'原明确动作来源失效，未执行新的资金动作。');CONTINUE;END IF;
   END IF;
  ELSE CONTINUE;END IF;
  action_value:=dg_native_bill_transport_action(operation.id,'bill_'||mode_value);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;lease_value:=gen_random_uuid()::text;expires:=dg_native_people_iso(created::timestamptz+interval '15 seconds');
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status=CASE WHEN mode_value='send' THEN 'submitting' WHEN interrupted AND status<>'needs_attention' THEN 'unknown' ELSE status END,send_attempts=send_attempts+CASE WHEN mode_value='send' THEN 1 ELSE 0 END,simulate_attempts=simulate_attempts+CASE WHEN mode_value='simulate' THEN 1 ELSE 0 END,lookups=lookups+CASE WHEN mode_value='query' THEN 1 ELSE 0 END,last_lookup_at=CASE WHEN mode_value='query' THEN created ELSE last_lookup_at END,next_action=NULL,lease_action=mode_value,lease_token=lease_value,lease_until=expires,version=version+1,updated_at=created WHERE id=operation.id;
  INSERT INTO _dg_native_bill_worker_leases VALUES(lease_value,operation.id,mode_value,operation.request_hash,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_value,created,expires,source_action.action_id);PERFORM dg_native_bill_refresh(action_value,operation.bill_id);PERFORM dg_native_bill_event(action_value,operation.bill_id,operation.id,CASE WHEN mode_value='send' THEN '已持久登记首次资金请求尝试，尚未核实付款或退款。' WHEN interrupted THEN '原租约已到期，仅查询同一请求；不重复付款、退款或关闭动作。' ELSE '沿原编号核对已明确请求的资金动作。' END);
  RETURN jsonb_build_object('operationId',operation.id,'leaseToken',lease_value,'mode',mode_value,'expiresAt',expires,'requestHash',operation.request_hash);
 END LOOP;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_bill_worker_context(target text,lease_value text,execute_value boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;lease _dg_native_bill_worker_leases%ROWTYPE;source_action _dg_native_bill_action_origins%ROWTYPE;reason_value text;
BEGIN
 PERFORM dg_native_reception_runtime(true);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO lease FROM _dg_native_bill_worker_leases WHERE lease_token=lease_value AND operation_id=target;
 IF operation.id IS NULL OR operation.lease_token IS DISTINCT FROM lease_value OR lease.lease_token IS NULL OR operation.lease_until<=dg_native_dining_now() OR operation.lease_until IS DISTINCT FROM lease.expires_at OR operation.lease_action IS DISTINCT FROM lease.mode OR lease.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR lease.request_hash<>operation.request_hash OR operation.request_hash<>dg_native_office_hash(operation.request_payload::jsonb) OR operation.send_attempts<>1 OR operation.provider_id<>'mock-payments' OR operation.simulated<>1 OR operation.status NOT IN('submitting','pending','unknown','needs_attention') THEN PERFORM dg_native_bill_error('FINANCIAL_WORKER_LEASE');END IF;
 IF execute_value THEN
  IF lease.mode='send' THEN reason_value:=dg_native_bill_quote_reason(operation.quote_id,NULL,true);
  ELSIF lease.mode IN('close','simulate') THEN SELECT * INTO source_action FROM _dg_native_bill_action_origins WHERE action_id=lease.source_action_id;reason_value:=CASE WHEN source_action.action_id IS NULL THEN '原明确动作缺失。' ELSE dg_native_bill_action_reason(operation.id,lease.mode,source_action.actor_meta,true) END;END IF;
  IF reason_value IS NOT NULL THEN PERFORM dg_native_bill_error('FINANCIAL_SOURCE_EXPIRED');END IF;
 END IF;
 RETURN jsonb_build_object('operationId',operation.id,'leaseToken',lease_value,'mode',lease.mode,'expiresAt',lease.expires_at,'requestHash',lease.request_hash,'request',operation.request_payload::jsonb,'scenario',operation.config_snapshot::jsonb->>'scenario','sourceExpiresAt',CASE WHEN lease.mode='send' THEN(SELECT expires_at FROM restaurant_financial_quotes WHERE id=operation.quote_id) ELSE lease.expires_at END);
END;$dg$;

CREATE FUNCTION dg_native_bill_worker_complete(target text,lease_value text,receipt jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;lease _dg_native_bill_worker_leases%ROWTYPE;action_value text;created text;result_value jsonb;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_bill_transport_lock(target);PERFORM dg_native_bill_worker_context(target,lease_value,false);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;
 IF receipt IS NOT NULL THEN RETURN dg_native_bill_receipt_apply(gen_random_uuid()::text,receipt,'worker');END IF;
 action_value:=dg_native_bill_transport_action(target,'bill_unknown');SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',target);UPDATE restaurant_financial_operations SET status=CASE WHEN error_code='FINANCIAL_RECONCILIATION_REQUIRED' THEN 'needs_attention' ELSE 'unknown' END,lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,error_code=CASE WHEN error_code='FINANCIAL_RECONCILIATION_REQUIRED' THEN error_code ELSE 'FINANCIAL_RESULT_UNKNOWN' END,error_message=CASE WHEN error_code='FINANCIAL_RECONCILIATION_REQUIRED' THEN error_message ELSE '通信结果尚未核实，保留原编号和退款额度，仅查询原请求，不重复资金动作。' END,version=version+1,updated_at=created WHERE id=target;PERFORM dg_native_bill_refresh(action_value,operation.bill_id);PERFORM dg_native_bill_event(action_value,operation.bill_id,target,'原资金请求结果未知，保留原请求与额度，仅允许核对。');RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',coalesce(operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED',false));
END;$dg$;

CREATE FUNCTION dg_native_bill_mock_receipt(target text,status_value text DEFAULT NULL,sequence_value bigint DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;remote mock_financial_operations%ROWTYPE;
BEGIN SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=target;IF remote.operation_id IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('operationId',operation.id,'kind',operation.kind,'requestHash',operation.request_hash,'restaurantId',b.restaurant_id,'billId',b.id,'merchantId',operation.merchant_id,'amountMinor',operation.amount_minor,'currency','CNY','remoteOperationId',remote.remote_operation_id,'remoteTransactionId',remote.remote_transaction_id,'status',coalesce(status_value,remote.status),'sequence',coalesce(sequence_value,remote.sequence),'simulated',true);
END;$dg$;

CREATE FUNCTION dg_native_bill_mock_record(target text,status_value text,sequence_value bigint,action_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;remote mock_financial_operations%ROWTYPE;created text;
BEGIN SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=target;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'mock_financial_operations',target);
 IF remote.operation_id IS NULL THEN INSERT INTO mock_financial_operations VALUES(operation.id,operation.request_hash,operation.request_payload,(CASE WHEN operation.kind='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||operation.id,(CASE WHEN operation.kind='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||operation.id,status_value,sequence_value,created,created);
 ELSE UPDATE mock_financial_operations SET status=status_value,sequence=sequence_value,updated_at=created WHERE operation_id=target;END IF;
END;$dg$;

CREATE FUNCTION dg_native_bill_mock_io(target text,lease_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE context_value jsonb;operation restaurant_financial_operations%ROWTYPE;remote mock_financial_operations%ROWTYPE;mode_value text;scenario_value text;action_value text;status_value text;sequence_value bigint;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_bill_transport_lock(target);context_value:=dg_native_bill_worker_context(target,lease_value,true);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=target;mode_value:=context_value->>'mode';scenario_value:=context_value->>'scenario';
 IF remote.operation_id IS NOT NULL AND(remote.request_hash<>operation.request_hash OR remote.payload::jsonb IS DISTINCT FROM operation.request_payload::jsonb) THEN PERFORM dg_native_bill_error('FINANCIAL_REQUEST_MISMATCH');END IF;
 IF mode_value='query' THEN RETURN jsonb_build_object('receipt',dg_native_bill_mock_receipt(target),'errorCode',NULL);END IF;
 IF mode_value='send' THEN
  IF remote.operation_id IS NOT NULL THEN RETURN jsonb_build_object('receipt',dg_native_bill_mock_receipt(target),'errorCode',NULL);END IF;
  IF scenario_value='unresolved' THEN RETURN jsonb_build_object('receipt',NULL,'errorCode','MOCK_FINANCIAL_UNRESOLVED');END IF;
  IF operation.kind='refund' AND(operation.parent_payment_id IS NULL OR operation.request_payload::jsonb->>'parentRemoteTransactionId' IS NULL) THEN PERFORM dg_native_bill_error('REFUND_UNAVAILABLE');END IF;
  status_value:=CASE WHEN operation.kind='payment' THEN 'pending' WHEN scenario_value='failed' THEN 'failed' ELSE 'succeeded' END;sequence_value:=CASE WHEN operation.kind='payment' THEN 1 ELSE 2 END;
 ELSIF mode_value='simulate' THEN
  IF remote.operation_id IS NULL OR operation.kind<>'payment' THEN PERFORM dg_native_bill_error('FINANCIAL_ACTION_UNAVAILABLE');END IF;IF remote.status<>'pending' THEN RETURN jsonb_build_object('receipt',dg_native_bill_mock_receipt(target),'errorCode',NULL);END IF;
  IF scenario_value='unresolved' THEN RETURN jsonb_build_object('receipt',NULL,'errorCode','MOCK_CHECKOUT_UNRESOLVED');END IF;status_value:=CASE WHEN scenario_value='failed' THEN 'failed' ELSE 'succeeded' END;sequence_value:=remote.sequence+1;
 ELSE
  IF remote.operation_id IS NULL OR operation.kind<>'payment' THEN RETURN jsonb_build_object('receipt',NULL,'errorCode',NULL);END IF;IF remote.status<>'pending' THEN RETURN jsonb_build_object('receipt',dg_native_bill_mock_receipt(target),'errorCode',NULL);END IF;status_value:='expired';sequence_value:=remote.sequence+1;
 END IF;
 action_value:=dg_native_bill_transport_action(target,'bill_mock',jsonb_build_object('mode',mode_value,'status',status_value,'sequence',sequence_value));PERFORM dg_native_bill_mock_record(target,status_value,sequence_value,action_value);
 IF scenario_value='response_lost' AND mode_value IN('send','simulate') THEN RETURN jsonb_build_object('receipt',NULL,'errorCode','MOCK_FINANCIAL_RESPONSE_LOST');END IF;
 RETURN jsonb_build_object('receipt',CASE WHEN mode_value='send' AND operation.kind='refund' THEN dg_native_bill_mock_receipt(target,'pending',1) ELSE dg_native_bill_mock_receipt(target) END,'errorCode',NULL);
END;$dg$;

CREATE FUNCTION dg_native_bill_mock_fixture(target text,input jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;operation restaurant_financial_operations%ROWTYPE;remote mock_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;action_value text;created text;sequence_value bigint;
BEGIN
 meta:=dg_native_bill_context('operation',target,NULL,NULL,NULL,NULL,true,true);IF NOT dg_native_bill_manager(meta) THEN PERFORM dg_native_bill_error('FORBIDDEN');END IF;PERFORM dg_native_restaurant_fields(input,ARRAY['version','status','confirmed']);SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target FOR UPDATE;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=target;
 IF input->'confirmed' IS DISTINCT FROM 'true'::jsonb OR input->>'status' IS NULL OR input->>'status' NOT IN('pending','succeeded','failed','expired') THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;IF dg_native_restaurant_integer(input->'version',1,9007199254740991)<>operation.version THEN PERFORM dg_native_bill_error('VERSION_CONFLICT');END IF;
 IF operation.provider_id<>'mock-payments' OR operation.simulated<>1 OR operation.status<>'unknown' OR operation.send_attempts<>1 OR operation.lease_token IS NOT NULL OR operation.next_action IS NOT NULL OR remote.operation_id IS NOT NULL AND remote.status<>'pending' OR EXISTS(SELECT 1 FROM _dg_native_bill_mock_fixture_origins WHERE operation_id=target) THEN PERFORM dg_native_bill_error('FINANCIAL_FIXTURE_UNAVAILABLE');END IF;
 action_value:=dg_native_dining_action(meta,'bill_fixture','party',b.party_id,input);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;sequence_value:=coalesce(remote.sequence,0)+1;INSERT INTO _dg_native_bill_mock_fixture_origins VALUES(target,action_value,sequence_value,created);PERFORM dg_native_bill_mock_record(target,input->>'status',sequence_value,action_value);PERFORM dg_native_bill_event(action_value,b.id,target,'经理已明确建立一次本地模拟远端事实，尚须查询并核对原请求，未直接改变收款或退款。');INSERT INTO _dg_native_bill_results VALUES(action_value,b.restaurant_id,b.id,(meta->>'partyAccessVersion')::bigint,created);RETURN action_value;
END;$dg$;

CREATE FUNCTION dg_native_bill_receipt_apply(event_value text,receipt jsonb,ingress_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;r restaurants%ROWTYPE;previous restaurant_financial_receipts%ROWTYPE;status_value text:=receipt->>'status';sequence_value bigint;payload_hash_value text;action_value text;created text;posting_value text;posted boolean;ignored boolean;failure_code text;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_restaurant_fields(receipt,ARRAY['operationId','kind','requestHash','restaurantId','billId','merchantId','amountMinor','currency','remoteOperationId','remoteTransactionId','status','sequence','simulated']);sequence_value:=dg_native_restaurant_integer(receipt->'sequence',1,9007199254740991);
 IF event_value IS NULL OR event_value!~'^[a-f0-9-]{36}$' OR ingress_value IS NULL OR ingress_value NOT IN('worker','callback') OR status_value IS NULL OR status_value NOT IN('pending','succeeded','failed','expired') OR receipt->'simulated' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_bill_error('VALIDATION_FAILED');END IF;
 PERFORM dg_native_bill_transport_lock(receipt->>'operationId');SELECT * INTO operation FROM restaurant_financial_operations WHERE id=receipt->>'operationId';SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;SELECT * INTO r FROM restaurants WHERE id=b.restaurant_id;
 IF operation.id IS NULL OR receipt->>'kind' IS DISTINCT FROM operation.kind OR receipt->>'requestHash' IS DISTINCT FROM operation.request_hash OR receipt->>'restaurantId' IS DISTINCT FROM b.restaurant_id OR receipt->>'billId' IS DISTINCT FROM b.id OR receipt->>'merchantId' IS DISTINCT FROM operation.merchant_id OR dg_native_restaurant_integer(receipt->'amountMinor',1,100000000)<>operation.amount_minor OR receipt->>'currency' IS DISTINCT FROM 'CNY' OR operation.provider_id<>'mock-payments' OR operation.simulated<>1 OR r.environment<>'mock' OR r.app_env IS DISTINCT FROM(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR receipt->>'remoteOperationId' IS DISTINCT FROM(CASE WHEN operation.kind='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||operation.id OR receipt->>'remoteTransactionId' IS DISTINCT FROM(CASE WHEN operation.kind='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||operation.id THEN PERFORM dg_native_bill_error('FINANCIAL_RECEIPT_MISMATCH');END IF;
 IF operation.send_attempts<>1 THEN PERFORM dg_native_bill_error('FINANCIAL_NOT_SENT');END IF;payload_hash_value:=dg_native_office_hash(receipt);SELECT * INTO previous FROM restaurant_financial_receipts WHERE event_id=event_value;
 IF previous.event_id IS NOT NULL THEN IF previous.operation_id<>operation.id OR previous.payload_hash<>payload_hash_value THEN PERFORM dg_native_bill_error('FINANCIAL_EVENT_CONFLICT');END IF;RETURN jsonb_build_object('duplicate',true,'applied',previous.applied=1,'attention',previous.attention=1);END IF;
 action_value:=dg_native_bill_transport_action(operation.id,'bill_receipt',receipt);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_receipts',event_value);INSERT INTO restaurant_financial_receipts VALUES(event_value,operation.id,payload_hash_value,receipt::text,status_value,sequence_value,0,0,created);INSERT INTO _dg_native_bill_receipt_origins VALUES(event_value,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),operation.request_hash,payload_hash_value,ingress_value,created);
 posted:=EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=operation.id);
 ignored:=status_value<>'succeeded' AND(posted AND operation.error_code IS DISTINCT FROM 'FINANCIAL_RECONCILIATION_REQUIRED' OR status_value='pending' AND operation.status IN('failed','expired','cancelled','stale') OR sequence_value<=operation.last_sequence AND NOT(status_value='pending' AND operation.status='unknown' AND sequence_value=operation.last_sequence));
 IF ignored THEN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET last_sequence=greatest(last_sequence,sequence_value),version=version+1,updated_at=created WHERE id=operation.id;PERFORM dg_native_bill_refresh(action_value,b.id);RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',false);
 END IF;
 -- The verified success and immutable posting survive any later projection failure.
 IF status_value='succeeded' AND NOT posted THEN
  posting_value:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(action_value,'restaurant_financial_postings',posting_value);INSERT INTO restaurant_financial_postings VALUES(posting_value,b.id,operation.id,operation.kind,operation.amount_minor,'CNY',operation.provider_id,operation.merchant_id,receipt->>'remoteTransactionId',r.environment,r.app_env,created);INSERT INTO _dg_native_bill_posting_origins VALUES(posting_value,event_value,operation.id,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_value);
 END IF;
 IF operation.error_code='FINANCIAL_RECONCILIATION_REQUIRED' AND status_value<>'succeeded' THEN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='needs_attention',last_sequence=greatest(last_sequence,sequence_value),lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;UPDATE restaurant_financial_receipts SET attention=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',true);
 END IF;
 BEGIN
  PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status=status_value,remote_operation_id=receipt->>'remoteOperationId',remote_transaction_id=receipt->>'remoteTransactionId',last_sequence=greatest(last_sequence,sequence_value),error_code=CASE WHEN status_value='failed' THEN 'FINANCIAL_VERIFIED_FAILED' END,error_message=CASE WHEN status_value='failed' THEN '模拟渠道明确未完成此资金操作；原收款和退款事实分别保留。' END,lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;
  UPDATE restaurant_financial_receipts SET applied=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);PERFORM dg_native_bill_event(action_value,b.id,operation.id,CASE WHEN status_value='succeeded' AND operation.kind='payment' THEN '已核实模拟收款并保留独立资金事实；菜品履行仍单独核对。' WHEN status_value='succeeded' THEN '已核实模拟退款；原收款不覆盖，退款单独登记。' WHEN status_value='pending' THEN '原资金入口已核实接收，尚未核实最终收款或退款。' WHEN status_value='expired' THEN '原收银入口已由可信结果核实关闭或到期。' ELSE '可信渠道明确未完成本次资金操作。' END);
  SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS failure_code=RETURNED_SQLSTATE;INSERT INTO _dg_native_bill_receipt_failures VALUES(event_value,failure_code,'billing_projection',created);PERFORM dg_native_dining_effect(action_value,'restaurant_financial_operations',operation.id);UPDATE restaurant_financial_operations SET status='needs_attention',last_sequence=greatest(last_sequence,sequence_value),error_code='FINANCIAL_RECONCILIATION_REQUIRED',error_message='可信回执与已核实资金事实已保留，本地投影仍待经理核对；仅查询原事实，不重复资金动作。',lease_token=NULL,lease_until=NULL,lease_action=NULL,next_action=NULL,version=version+1,updated_at=created WHERE id=operation.id;UPDATE restaurant_financial_receipts SET attention=1 WHERE event_id=event_value;PERFORM dg_native_bill_refresh(action_value,b.id);PERFORM dg_native_bill_event(action_value,b.id,operation.id,'可信资金事实已保留，投影异常转经理核对；未伪造结算或抹除原事实。');RETURN jsonb_build_object('duplicate',false,'applied',false,'attention',true);
 END;RETURN jsonb_build_object('duplicate',false,'applied',true,'attention',false);
END;$dg$;

CREATE FUNCTION dg_native_bill_receipt_document(target text,session_value text DEFAULT NULL,token_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;b restaurant_bills%ROWTYPE;t jsonb;
BEGIN
 meta:=dg_native_bill_context('bill',target,session_value,token_value);SELECT * INTO b FROM restaurant_bills WHERE id=target;t:=dg_native_bill_totals(b.id);IF b.status NOT IN('paid','partially_refunded','refunded','void') OR b.settled_at IS NULL OR b.attention_reason IS NOT NULL THEN PERFORM dg_native_bill_error('BILL_NOT_SETTLED');END IF;
 RETURN jsonb_build_object('billId',b.id,'number',b.number,'orderNumber',(SELECT number FROM restaurant_orders WHERE id=b.order_id),'restaurantName',(SELECT name FROM restaurants WHERE id=b.restaurant_id),'currency','CNY','totalMinor',b.amount_minor,'paidMinor',(t->>'paid')::bigint,'refundedMinor',(t->>'refunded')::bigint,'settledAt',b.settled_at,'simulated',true,'notice','明确本地模拟收据，无真实资金往来，不是税务发票。','lines',b.snapshot::jsonb,'transactions',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',posting.id,'kind',posting.kind,'amountMinor',posting.amount_minor,'createdAt',posting.created_at) ORDER BY posting.created_at,posting.id),'[]') FROM restaurant_financial_postings posting WHERE posting.bill_id=b.id));
END;$dg$;

CREATE FUNCTION dg_native_bill_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;bill_value text;operation_id_value text;b restaurant_bills%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;mutable_fields text[];
BEGIN
 IF table_value NOT IN('restaurant_bills','restaurant_financial_operations','restaurant_financial_receipts','restaurant_financial_postings','restaurant_financial_events','mock_financial_operations') THEN RETURN false;END IF;
 record_value:=CASE WHEN table_value='restaurant_financial_receipts' THEN j->>'event_id' WHEN table_value='mock_financial_operations' THEN j->>'operation_id' ELSE j->>'id' END;
 operation_id_value:=CASE WHEN table_value='restaurant_financial_operations' THEN j->>'id' WHEN table_value IN('restaurant_financial_receipts','restaurant_financial_postings','mock_financial_operations') THEN j->>'operation_id' END;
 bill_value:=CASE WHEN table_value='restaurant_bills' THEN j->>'id' WHEN table_value='restaurant_financial_events' THEN j->>'bill_id' ELSE(SELECT bill_id FROM restaurant_financial_operations WHERE id=operation_id_value) END;SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;
 SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id AND actual.restaurant_id=b.restaurant_id AND actual.resource_id=b.party_id AND actual.kind IN('bill_action','bill_fixture','bill_send','bill_query','bill_close','bill_simulate','bill_unknown','bill_stale','bill_action_blocked','bill_mock','bill_receipt','order_receipt') ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;
 IF actual_action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' OR NOT dg_native_dining_changed(table_value,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial history requires its exact scoped durable operation';END IF;
 IF table_value='restaurant_financial_operations' THEN
  mutable_fields:=ARRAY['status','version','send_attempts','simulate_attempts','lookups','last_lookup_at','next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','lease_action','lease_token','lease_until','remote_operation_id','remote_transaction_id','last_sequence','error_code','error_message','updated_at'];
  IF operation_value<>'UPDATE' OR j-mutable_fields IS DISTINCT FROM previous-mutable_fields OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'updated_at'<>actual_action.created_at OR(j->>'send_attempts')::bigint NOT BETWEEN 0 AND 1 OR(j->>'simulate_attempts')::bigint NOT BETWEEN 0 AND 1 OR(j->>'send_attempts')::bigint<(previous->>'send_attempts')::bigint OR(j->>'simulate_attempts')::bigint<(previous->>'simulate_attempts')::bigint OR(j->>'lookups')::bigint<(previous->>'lookups')::bigint OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport preserves immutable request, actor, amount and monotone attempts';END IF;
  IF(j->>'send_attempts')::bigint>(previous->>'send_attempts')::bigint AND(actual_action.kind<>'bill_send' OR previous->>'status'<>'queued' OR(previous->>'send_attempts')::bigint<>0) OR(j->>'simulate_attempts')::bigint>(previous->>'simulate_attempts')::bigint AND(actual_action.kind<>'bill_simulate' OR previous->>'status'<>'pending' OR(previous->>'simulate_attempts')::bigint<>0) OR(j->>'lookups')::bigint>(previous->>'lookups')::bigint AND actual_action.kind<>'bill_query' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Sending, explicit simulation and original lookup each retain their actual single attempt';END IF;
  IF j->>'remote_operation_id' IS NOT NULL AND j->>'remote_operation_id' IS DISTINCT FROM(CASE WHEN j->>'kind'='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||record_value OR j->>'remote_transaction_id' IS NOT NULL AND j->>'remote_transaction_id' IS DISTINCT FROM(CASE WHEN j->>'kind'='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||record_value OR previous->>'remote_operation_id' IS NOT NULL AND j->>'remote_operation_id' IS DISTINCT FROM previous->>'remote_operation_id' OR previous->>'remote_transaction_id' IS NOT NULL AND j->>'remote_transaction_id' IS DISTINCT FROM previous->>'remote_transaction_id' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Remote money identities remain the exact original operation';END IF;
  IF actual_action.kind='bill_action' AND j-ARRAY['next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','version','updated_at'] IS DISTINCT FROM previous-ARRAY['next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A human request schedules only the original action and cannot fabricate funds';END IF;
  IF previous->>'error_code'='FINANCIAL_RECONCILIATION_REQUIRED' AND j->>'error_code' IS DISTINCT FROM 'FINANCIAL_RECONCILIATION_REQUIRED' AND NOT(actual_action.kind='bill_receipt' AND EXISTS(SELECT 1 FROM _dg_native_bill_receipt_origins origin JOIN restaurant_financial_receipts receipt ON receipt.event_id=origin.event_id WHERE origin.action_id=actual_action.id AND receipt.operation_id=record_value AND receipt.status='succeeded')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only a fresh verified success can repair a failed money projection';END IF;
  IF j->>'status'='succeeded' AND NOT EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Success requires a separate verified immutable posting';END IF;
 ELSIF table_value='restaurant_bills' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','attention_reason','settled_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'updated_at'<>actual_action.created_at OR previous->>'settled_at' IS NOT NULL AND j->>'settled_at' IS DISTINCT FROM previous->>'settled_at' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Money transport cannot rewrite bill prices, identity or original settlement time';END IF;
 ELSIF table_value='restaurant_financial_postings' THEN
  IF operation_value<>'INSERT' OR actual_action.kind<>'bill_receipt' OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funds facts are append only and require a verified receipt';END IF;
 ELSIF table_value='restaurant_financial_receipts' THEN
  IF actual_action.kind<>'bill_receipt' OR(operation_value='INSERT' AND((j->>'applied')::bigint<>0 OR(j->>'attention')::bigint<>0 OR j->>'created_at'<>actual_action.created_at)) OR(operation_value='UPDATE' AND(j-ARRAY['applied','attention'] IS DISTINCT FROM previous-ARRAY['applied','attention'] OR(previous->>'applied')::bigint<>0 OR(previous->>'attention')::bigint<>0 OR(j->>'applied')::bigint+(j->>'attention')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt content is immutable and its single application result is retained';END IF;
 ELSIF table_value='mock_financial_operations' THEN
  IF actual_action.kind NOT IN('bill_mock','bill_fixture') OR j->>'updated_at'<>actual_action.created_at OR operation_value='UPDATE' AND(j-ARRAY['status','sequence','updated_at'] IS DISTINCT FROM previous-ARRAY['status','sequence','updated_at'] OR previous->>'status'<>'pending' OR(j->>'sequence')::bigint<=(previous->>'sequence')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock remote facts retain original payload and monotone pending to final transitions';END IF;
 ELSE
  IF operation_value<>'INSERT' OR j->>'kind'<>actual_action.kind OR j->>'actor_id'<>actual_action.actor_id OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial events retain their actual scoped actor and action';END IF;
 END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_bill_transport_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);record_value text;actual_action _dg_native_dining_actions%ROWTYPE;revision_value bigint;
BEGIN
 record_value:=CASE WHEN TG_TABLE_NAME='restaurant_financial_receipts' THEN j->>'event_id' WHEN TG_TABLE_NAME='mock_financial_operations' THEN j->>'operation_id' ELSE j->>'id' END;SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;
 IF actual_action.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial row revisions retain their actual effect';END IF;
 IF TG_TABLE_NAME='restaurant_financial_operations' THEN INSERT INTO _dg_native_bill_operation_revisions VALUES(record_value,(j->>'version')::bigint,actual_action.id,dg_native_office_hash(j),j->>'updated_at');
 ELSIF TG_TABLE_NAME='mock_financial_operations' THEN INSERT INTO _dg_native_bill_mock_revisions VALUES(record_value,(j->>'sequence')::bigint,actual_action.id,dg_native_office_hash(j),j->>'updated_at');
 ELSE SELECT coalesce(max(revision),0)+1 INTO revision_value FROM _dg_native_bill_receipt_revisions WHERE event_id=record_value;INSERT INTO _dg_native_bill_receipt_revisions VALUES(record_value,revision_value,actual_action.id,dg_native_office_hash(j),actual_action.created_at);END IF;RETURN NEW;
END;$dg$;
DO $bill_transport_revisions$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_financial_operations','restaurant_financial_receipts','mock_financial_operations'] LOOP EXECUTE format('CREATE TRIGGER native_bill_transport_revision AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_bill_transport_revision()',table_value);END LOOP;END;$bill_transport_revisions$;

CREATE FUNCTION dg_native_bill_transport_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);target text;operation restaurant_financial_operations%ROWTYPE;b restaurant_bills%ROWTYPE;lease _dg_native_bill_worker_leases%ROWTYPE;receipt restaurant_financial_receipts%ROWTYPE;receipt_origin _dg_native_bill_receipt_origins%ROWTYPE;posting restaurant_financial_postings%ROWTYPE;remote mock_financial_operations%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;action_origin _dg_native_bill_action_origins%ROWTYPE;payload jsonb;current_runtime text;
BEGIN
 SELECT runtime_id INTO current_runtime FROM _dg_native_runtime_control WHERE id=1;
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=j->>'id';IF actual_action.kind NOT IN('bill_action','bill_fixture','bill_send','bill_query','bill_close','bill_simulate','bill_unknown','bill_stale','bill_action_blocked','bill_mock','bill_receipt') THEN RETURN NULL;END IF;
  IF actual_action.kind IN('bill_action','bill_fixture') THEN
   IF NOT EXISTS(SELECT 1 FROM _dg_native_bill_results result_value WHERE result_value.action_id=actual_action.id AND result_value.restaurant_id=actual_action.restaurant_id AND result_value.created_at=actual_action.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial human actions retain their immutable scoped result';END IF;
  ELSIF NOT EXISTS(SELECT 1 FROM _dg_native_bill_worker_leases WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_revisions WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_mock_revisions WHERE action_id=actual_action.id) AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_receipt_origins WHERE action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport actions have their actual immutable lease, revision or receipt';END IF;RETURN NULL;
 END IF;
 target:=CASE WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'id' WHEN TG_TABLE_NAME='restaurant_financial_postings' OR TG_TABLE_NAME='mock_financial_operations' OR TG_TABLE_NAME IN('_dg_native_bill_worker_leases','_dg_native_bill_posting_origins','_dg_native_bill_operation_revisions','_dg_native_bill_mock_revisions','_dg_native_bill_action_origins','_dg_native_bill_mock_fixture_origins') THEN j->>'operation_id' WHEN TG_TABLE_NAME='restaurant_financial_receipts' THEN j->>'operation_id' WHEN TG_TABLE_NAME IN('_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures') THEN(SELECT operation_id FROM restaurant_financial_receipts WHERE event_id=j->>'event_id') END;
 SELECT * INTO operation FROM restaurant_financial_operations WHERE id=target;SELECT * INTO b FROM restaurant_bills WHERE id=operation.bill_id;IF operation.id IS NULL OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_origins origin WHERE origin.operation_id=operation.id AND origin.runtime_id=current_runtime) OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_operation_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.operation_id=operation.id AND revision.version=operation.version AND revision.row_hash=dg_native_office_hash(to_jsonb(operation)) AND revision.created_at=operation.updated_at AND revision_action.restaurant_id=b.restaurant_id AND revision_action.resource_id=b.party_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport retains exact native request and current full row revision';END IF;
 IF operation.lease_token IS NOT NULL THEN
  SELECT * INTO lease FROM _dg_native_bill_worker_leases WHERE lease_token=operation.lease_token AND operation_id=operation.id;
  IF lease.lease_token IS NULL OR lease.runtime_id<>current_runtime OR lease.request_hash<>operation.request_hash OR lease.mode IS DISTINCT FROM operation.lease_action OR lease.expires_at IS DISTINCT FROM operation.lease_until OR lease.expires_at<>dg_native_people_iso(lease.created_at::timestamptz+interval '15 seconds') OR operation.send_attempts<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial lease keeps its fixed original deadline, request and attempt';END IF;
 ELSIF operation.lease_until IS NOT NULL OR operation.lease_action IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial lease columns clear together';END IF;
 IF TG_TABLE_NAME='_dg_native_bill_worker_leases' THEN
  SELECT * INTO lease FROM _dg_native_bill_worker_leases WHERE lease_token=j->>'lease_token';SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=lease.action_id;
  IF actual_action.kind<>'bill_'||lease.mode OR actual_action.created_at<>lease.created_at OR actual_action.restaurant_id<>b.restaurant_id OR actual_action.resource_id<>b.party_id OR lease.runtime_id<>current_runtime OR lease.request_hash<>operation.request_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial leases originate in the actual matching worker action';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text THEN
   IF operation.lease_token IS DISTINCT FROM lease.lease_token OR lease.expires_at<=dg_native_dining_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New financial lease must commit within its fixed original deadline';END IF;
   PERFORM dg_native_bill_worker_context(operation.id,lease.lease_token,true);
  END IF;
 ELSIF TG_TABLE_NAME IN('restaurant_financial_receipts','_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures','restaurant_financial_postings','_dg_native_bill_posting_origins') THEN
  IF TG_TABLE_NAME='restaurant_financial_postings' THEN SELECT * INTO posting FROM restaurant_financial_postings WHERE id=j->>'id';SELECT event_id INTO target FROM _dg_native_bill_posting_origins WHERE posting_id=posting.id;
  ELSIF TG_TABLE_NAME='_dg_native_bill_posting_origins' THEN SELECT * INTO posting FROM restaurant_financial_postings WHERE id=j->>'posting_id';target:=j->>'event_id';ELSE target:=j->>'event_id';END IF;
  SELECT * INTO receipt FROM restaurant_financial_receipts WHERE event_id=target;SELECT * INTO receipt_origin FROM _dg_native_bill_receipt_origins WHERE event_id=target;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=receipt_origin.action_id;payload:=receipt.payload::jsonb;
  IF receipt.event_id IS NULL OR receipt_origin.event_id IS NULL OR receipt.operation_id<>operation.id OR receipt_origin.runtime_id<>current_runtime OR receipt_origin.request_hash<>operation.request_hash OR receipt_origin.receipt_hash<>receipt.payload_hash OR receipt.payload_hash<>dg_native_office_hash(payload) OR actual_action.kind<>'bill_receipt' OR actual_action.body_hash<>receipt.payload_hash OR actual_action.created_at<>receipt.created_at OR receipt_origin.created_at<>receipt.created_at OR actual_action.restaurant_id<>b.restaurant_id OR actual_action.resource_id<>b.party_id OR receipt.status<>payload->>'status' OR receipt.sequence<>(payload->>'sequence')::bigint OR payload->>'operationId'<>operation.id OR payload->>'requestHash'<>operation.request_hash OR payload->>'billId'<>b.id OR payload->>'restaurantId'<>b.restaurant_id OR payload->>'merchantId'<>operation.merchant_id OR(payload->>'amountMinor')::bigint<>operation.amount_minor OR payload->>'currency'<>'CNY' OR payload->'simulated' IS DISTINCT FROM 'true'::jsonb OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_receipt_revisions revision WHERE revision.event_id=receipt.event_id AND revision.revision=(SELECT max(revision) FROM _dg_native_bill_receipt_revisions WHERE event_id=receipt.event_id) AND revision.row_hash=dg_native_office_hash(to_jsonb(receipt)) AND revision.action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial receipts retain exact verified payload, immutable origin and result revision';END IF;
  IF posting.id IS NOT NULL THEN
   IF receipt.status<>'succeeded' OR posting.operation_id<>operation.id OR posting.bill_id<>b.id OR posting.kind<>operation.kind OR posting.amount_minor<>operation.amount_minor OR posting.currency<>'CNY' OR posting.provider_id<>operation.provider_id OR posting.merchant_id<>operation.merchant_id OR posting.remote_transaction_id<>payload->>'remoteTransactionId' OR posting.environment<>'mock' OR posting.app_env<>(SELECT app_env FROM _dg_native_runtime_control WHERE id=1) OR posting.created_at<>receipt.created_at OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_posting_origins origin WHERE origin.posting_id=posting.id AND origin.operation_id=operation.id AND origin.event_id=receipt.event_id AND origin.runtime_id=current_runtime AND origin.action_id=actual_action.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Immutable money postings originate only in the exact verified success, amount and environment';END IF;
  END IF;
  IF receipt.status='succeeded' AND NOT EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=operation.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every verified financial success retains a posting even if projection failed';END IF;
 ELSIF TG_TABLE_NAME IN('mock_financial_operations','_dg_native_bill_mock_revisions','_dg_native_bill_mock_fixture_origins') THEN
  SELECT * INTO remote FROM mock_financial_operations WHERE operation_id=operation.id;SELECT revision_action.* INTO actual_action FROM _dg_native_bill_mock_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.operation_id=operation.id AND revision.sequence=remote.sequence AND revision.row_hash=dg_native_office_hash(to_jsonb(remote)) AND revision.created_at=remote.updated_at;
  IF remote.operation_id IS NULL OR remote.request_hash<>operation.request_hash OR remote.payload::jsonb IS DISTINCT FROM operation.request_payload::jsonb OR actual_action.id IS NULL OR actual_action.kind NOT IN('bill_mock','bill_fixture') OR remote.remote_operation_id<>(CASE WHEN operation.kind='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||operation.id OR remote.remote_transaction_id<>(CASE WHEN operation.kind='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||operation.id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock funds facts retain original request, matching identities and actual revision';END IF;
  IF actual_action.kind='bill_mock' AND actual_action.transaction_id=pg_current_xact_id()::text THEN PERFORM dg_native_bill_worker_context(operation.id,operation.lease_token,true);END IF;
  IF actual_action.kind='bill_fixture' AND NOT EXISTS(SELECT 1 FROM _dg_native_bill_mock_fixture_origins origin WHERE origin.operation_id=operation.id AND origin.action_id=actual_action.id AND origin.sequence=remote.sequence AND origin.created_at=actual_action.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock fixture is an explicit single manager operation';END IF;
 ELSIF TG_TABLE_NAME='_dg_native_bill_action_origins' THEN
  SELECT * INTO action_origin FROM _dg_native_bill_action_origins WHERE action_id=j->>'action_id';SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=action_origin.action_id;
  IF actual_action.kind<>'bill_action' OR actual_action.created_at<>action_origin.created_at OR actual_action.actor_id IS DISTINCT FROM action_origin.actor_meta->>'actorId' OR actual_action.session_id IS DISTINCT FROM action_origin.actor_meta->>'sessionId' OR actual_action.focus_version IS DISTINCT FROM(action_origin.actor_meta->>'focusVersion')::bigint OR actual_action.resource_id<>b.party_id OR actual_action.restaurant_id<>b.restaurant_id OR action_origin.mode IS DISTINCT FROM operation.next_action THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial action preserves its exact current person, session, mode and scope';END IF;
  IF action_origin.mode<>'query' AND dg_native_bill_action_reason(operation.id,action_origin.mode,action_origin.actor_meta) IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit money action retains actual source through commit';END IF;
 END IF;RETURN NULL;
END;$dg$;
DO $bill_transport_final$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_financial_operations','restaurant_financial_receipts','restaurant_financial_postings','mock_financial_operations','_dg_native_bill_worker_leases','_dg_native_bill_posting_origins','_dg_native_bill_operation_revisions','_dg_native_bill_receipt_origins','_dg_native_bill_receipt_revisions','_dg_native_bill_receipt_failures','_dg_native_bill_mock_revisions','_dg_native_bill_action_origins','_dg_native_bill_mock_fixture_origins','_dg_native_dining_actions'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER native_bill_transport_final AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_bill_transport_final()',table_value);END LOOP;END;$bill_transport_final$;

CREATE OR REPLACE FUNCTION dg_native_bill_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);previous jsonb:=to_jsonb(OLD);record_value text;bill_value text;restaurant_value text;party_value text;actual_action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF dg_native_bill_transport_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 record_value:=CASE WHEN TG_TABLE_NAME='restaurant_payment_configs' THEN j->>'restaurant_id' ELSE j->>'id' END;
 IF TG_OP='DELETE' OR NOT dg_native_dining_changed(TG_TABLE_NAME,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native financial records require the exact durable scoped operation';END IF;
 IF TG_TABLE_NAME='restaurant_payment_configs' THEN restaurant_value:=j->>'restaurant_id';ELSE bill_value:=CASE WHEN TG_TABLE_NAME='restaurant_bills' THEN j->>'id' ELSE j->>'bill_id' END;SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_bills WHERE id=bill_value;IF TG_TABLE_NAME='restaurant_bills' THEN restaurant_value:=j->>'restaurant_id';party_value:=j->>'party_id';END IF;END IF;
 SELECT op.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions op ON op.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND op.transaction_id=effect.transaction_id AND op.restaurant_id=restaurant_value AND op.resource_id=coalesce(party_value,restaurant_value) AND op.kind IN('bill_config','bill_review','bill_refund_review','bill_confirm','bill_withdraw') ORDER BY op.created_at DESC,op.id DESC LIMIT 1;
 IF actual_action.id IS NULL OR j->>'updated_at' IS NOT NULL AND j->>'updated_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial changes retain the original action, clock and store';END IF;
 IF TG_TABLE_NAME='restaurant_payment_configs' THEN
  IF actual_action.kind<>'bill_config' OR actual_action.actor_type<>'staff' OR j->>'merchant_id'<>'mock-merchant:'||restaurant_value OR j->>'provider_id' NOT IN('mock-payments','external-payments') OR(j->>'enabled')::bigint NOT IN(0,1) OR j->>'provider_id'='external-payments' AND(j->>'enabled')::bigint<>0 OR(j->>'version')::bigint<>(CASE WHEN TG_OP='INSERT' THEN 1 ELSE(previous->>'version')::bigint+1 END) OR TG_OP='UPDATE' AND j-ARRAY['provider_id','enabled','scenario','version','updated_at'] IS DISTINCT FROM previous-ARRAY['provider_id','enabled','scenario','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Payment configuration retains a derived merchant and explicit disabled real provider';END IF;
 ELSIF TG_TABLE_NAME='restaurant_bills' THEN
  IF TG_OP='INSERT' THEN IF actual_action.kind<>'bill_review' OR(j->>'version')::bigint<>1 OR j->>'created_at'<>actual_action.created_at OR j->>'status'<>'open' OR j->>'settled_at' IS NOT NULL OR j->>'attention_reason' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills originate in a server review before any funds fact';END IF;
  ELSE
   IF(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['version','order_content_version','amount_minor','snapshot','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','order_content_version','amount_minor','snapshot','status','attention_reason','settled_at','updated_at'] OR previous->>'settled_at' IS NOT NULL AND j->>'settled_at' IS DISTINCT FROM previous->>'settled_at' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills preserve their original identity, settlement clock and monotone revision';END IF;
   IF j-ARRAY['version','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','attention_reason','settled_at','updated_at'] AND(actual_action.kind<>'bill_review' OR EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE bill_id=bill_value) OR EXISTS(SELECT 1 FROM restaurant_financial_operations WHERE bill_id=bill_value AND status IN('queued','submitting','pending','unknown','needs_attention'))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial attempts or facts cannot be overwritten by a new price snapshot';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_quotes' THEN
  IF TG_OP='INSERT' THEN IF actual_action.kind NOT IN('bill_review','bill_refund_review') OR j->>'status'<>'current' OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial quotes originate in an actual current review';END IF;
  ELSIF j-'status' IS DISTINCT FROM previous-'status' OR previous->>'status'<>'current' OR j->>'status' NOT IN('consumed','superseded') OR j->>'status'='consumed' AND actual_action.kind<>'bill_confirm' OR j->>'status'='superseded' AND actual_action.kind NOT IN('bill_review','bill_refund_review') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='The original quote payload, actor and expiry cannot be rewritten';END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_operations' THEN
  IF TG_OP='INSERT' THEN
   IF actual_action.kind<>'bill_confirm' OR j->>'status'<>'queued' OR(j->>'version')::bigint<>1 OR(j->>'send_attempts')::bigint<>0 OR(j->>'simulate_attempts')::bigint<>0 OR(j->>'lookups')::bigint<>0 OR(j->>'last_sequence')::bigint<>0 OR(j->>'simulated')::bigint<>1 OR j->>'created_at'<>actual_action.created_at OR j->>'lease_token' IS NOT NULL OR j->>'lease_until' IS NOT NULL OR j->>'lease_action' IS NOT NULL OR j->>'next_action' IS NOT NULL OR j->>'remote_operation_id' IS NOT NULL OR j->>'remote_transaction_id' IS NOT NULL OR j->>'error_code' IS NOT NULL OR j->>'error_message' IS NOT NULL OR j->>'last_lookup_at' IS NOT NULL OR j->>'action_actor_id' IS NOT NULL OR j->>'action_session_id' IS NOT NULL OR j->>'action_focus_version' IS NOT NULL OR j->>'action_party_access_version' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit confirmation creates only an unsent immutable financial request';END IF;
  ELSIF actual_action.kind<>'bill_withdraw' OR previous->>'status'<>'queued' OR(previous->>'send_attempts')::bigint<>0 OR previous->>'lease_token' IS NOT NULL OR j->>'status'<>'cancelled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only an unsent request can be locally cancelled; no funds fact is fabricated';END IF;
 ELSIF TG_TABLE_NAME='restaurant_financial_events' THEN
  IF TG_OP<>'INSERT' OR j->>'actor_id'<>actual_action.actor_id OR j->>'kind'<>actual_action.kind OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial events retain their original actor and clock';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Trusted financial transport and postings are not enabled by the review stage';END IF;RETURN NEW;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_bill_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);b restaurant_bills%ROWTYPE;o restaurant_orders%ROWTYPE;q restaurant_financial_quotes%ROWTYPE;operation restaurant_financial_operations%ROWTYPE;config restaurant_payment_configs%ROWTYPE;origin _dg_native_bill_origins%ROWTYPE;quote_origin _dg_native_bill_quote_origins%ROWTYPE;operation_origin _dg_native_bill_operation_origins%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;payload jsonb;state_value jsonb;bill_value text;meta jsonb;
BEGIN
 IF TG_TABLE_NAME='_dg_native_dining_actions' THEN
  SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=j->>'id';IF actual_action.kind NOT IN('bill_config','bill_review','bill_refund_review','bill_confirm','bill_withdraw') THEN RETURN NULL;END IF;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_bill_results result_value WHERE result_value.action_id=actual_action.id AND result_value.restaurant_id=actual_action.restaurant_id AND result_value.created_at=actual_action.created_at AND(result_value.bill_id IS NULL AND actual_action.kind='bill_config' OR EXISTS(SELECT 1 FROM restaurant_bills bill WHERE bill.id=result_value.bill_id AND bill.party_id=actual_action.resource_id))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial actions require their actual immutable result and original resource';END IF;RETURN NULL;
 END IF;
 IF TG_TABLE_NAME IN('restaurant_payment_configs','_dg_native_bill_config_revisions') THEN
  SELECT * INTO config FROM restaurant_payment_configs WHERE restaurant_id=j->>'restaurant_id';SELECT op.* INTO actual_action FROM _dg_native_bill_config_revisions revision JOIN _dg_native_dining_actions op ON op.id=revision.action_id WHERE revision.restaurant_id=config.restaurant_id AND revision.version=config.version AND revision.provider_id=config.provider_id AND revision.enabled=config.enabled AND revision.merchant_id=config.merchant_id AND revision.scenario=config.scenario AND revision.created_at=config.updated_at;
  meta:=jsonb_build_object('actorType',actual_action.actor_type,'actorId',actual_action.actor_id,'actorEpoch',actual_action.actor_epoch,'grantVersion',actual_action.grant_version,'restaurantId',config.restaurant_id);
  IF actual_action.id IS NULL OR actual_action.kind<>'bill_config' OR NOT dg_native_bill_manager(meta) OR actual_action.body_hash<>dg_native_office_hash(jsonb_build_object('version',config.version-1,'providerId',config.provider_id,'enabled',config.enabled=1,'scenario',config.scenario,'confirmed',true)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='The exact current manager and confirmed revision authorize payment configuration';END IF;RETURN NULL;
 END IF;
 bill_value:=CASE WHEN TG_TABLE_NAME='restaurant_bills' THEN j->>'id' WHEN TG_TABLE_NAME='_dg_native_bill_origins' OR TG_TABLE_NAME='_dg_native_bill_revisions' THEN j->>'bill_id' WHEN TG_TABLE_NAME='restaurant_financial_quotes' THEN j->>'bill_id' WHEN TG_TABLE_NAME='_dg_native_bill_quote_origins' THEN(SELECT bill_id FROM restaurant_financial_quotes WHERE id=j->>'quote_id') WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'bill_id' WHEN TG_TABLE_NAME='_dg_native_bill_operation_origins' THEN(SELECT bill_id FROM restaurant_financial_operations WHERE id=j->>'operation_id') END;
 SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;SELECT * INTO o FROM restaurant_orders WHERE id=b.order_id;SELECT * INTO origin FROM _dg_native_bill_origins WHERE bill_id=b.id;state_value:=dg_native_bill_state(b.id);
 IF b.id IS NULL OR origin.bill_id IS NULL OR origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.order_id<>o.id OR origin.party_id<>o.party_id OR b.party_id<>o.party_id OR b.restaurant_id<>o.restaurant_id OR origin.created_at<>b.created_at OR b.number<>'B-'||substring(o.number FROM 3) OR b.status<>state_value->>'status' OR b.attention_reason IS DISTINCT FROM state_value->>'attentionReason' OR NOT EXISTS(SELECT 1 FROM _dg_native_bill_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.bill_id=b.id AND revision.version=b.version AND revision.row_hash=dg_native_office_hash(to_jsonb(b)) AND revision.created_at=b.updated_at AND revision_action.kind IN('bill_review','bill_confirm','bill_withdraw','bill_action','bill_fixture','bill_send','bill_query','bill_close','bill_simulate','bill_unknown','bill_stale','bill_action_blocked','bill_receipt','order_receipt')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Bills retain exact native order, derived totals, state and full row revision';END IF;
 IF b.amount_minor<>(SELECT coalesce(sum((line->>'subtotalMinor')::bigint),0) FROM jsonb_array_elements(b.snapshot::jsonb) line) OR EXISTS(SELECT 1 FROM jsonb_array_elements(b.snapshot::jsonb) line WHERE(line->>'subtotalMinor')::bigint<>(line->>'unitPriceMinor')::bigint*(line->>'quantity')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Server bill totals equal the immutable original line arithmetic';END IF;
 IF EXISTS(SELECT 1 FROM _dg_native_bill_revisions revision JOIN _dg_native_dining_actions revision_action ON revision_action.id=revision.action_id WHERE revision.bill_id=b.id AND revision.version=b.version AND revision_action.kind='bill_review' AND revision_action.transaction_id=pg_current_xact_id()::text) AND(b.order_content_version<>o.content_version OR b.snapshot::jsonb IS DISTINCT FROM dg_native_bill_lines(o.id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A new review snapshots exactly the current accepted quantities and original prices';END IF;
 IF TG_TABLE_NAME IN('restaurant_financial_quotes','_dg_native_bill_quote_origins') THEN
  SELECT * INTO q FROM restaurant_financial_quotes WHERE id=CASE WHEN TG_TABLE_NAME='restaurant_financial_quotes' THEN j->>'id' ELSE j->>'quote_id' END;SELECT * INTO quote_origin FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=quote_origin.action_id;payload:=q.payload::jsonb;
  IF quote_origin.quote_id IS NULL OR quote_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR quote_origin.payload_hash<>q.hash OR q.hash<>dg_native_office_hash(payload) OR q.id<>payload->>'id' OR q.bill_id<>b.id OR payload->>'billId'<>b.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR payload->>'partyId'<>o.party_id OR payload->>'expiresAt'<>q.expires_at OR q.created_at<>quote_origin.created_at OR q.expires_at<>quote_origin.expires_at OR q.expires_at<>dg_native_people_iso(q.created_at::timestamptz+interval '120 seconds') OR actual_action.created_at<>q.created_at OR actual_action.kind<>(CASE WHEN q.kind='payment' THEN 'bill_review' ELSE 'bill_refund_review' END) OR actual_action.actor_id IS DISTINCT FROM q.actor_id OR quote_origin.actor_meta->>'actorId' IS DISTINCT FROM q.actor_id OR quote_origin.actor_meta->>'sessionId' IS DISTINCT FROM q.session_id OR(quote_origin.actor_meta->>'focusVersion')::bigint IS DISTINCT FROM q.focus_version THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial quotes bind exact original actor, payload, fixed two minute deadline and runtime';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text AND(q.expires_at<=dg_native_dining_now() OR q.kind='payment' AND NOT dg_native_order_source(quote_origin.actor_meta,o.party_id) OR q.kind='refund' AND NOT dg_native_bill_manager(quote_origin.actor_meta)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='New financial review must commit with its original actual authority';END IF;
 ELSIF TG_TABLE_NAME IN('restaurant_financial_operations','_dg_native_bill_operation_origins') THEN
  SELECT * INTO operation FROM restaurant_financial_operations WHERE id=CASE WHEN TG_TABLE_NAME='restaurant_financial_operations' THEN j->>'id' ELSE j->>'operation_id' END;SELECT * INTO operation_origin FROM _dg_native_bill_operation_origins WHERE operation_id=operation.id;SELECT * INTO q FROM restaurant_financial_quotes WHERE id=operation.quote_id;SELECT * INTO quote_origin FROM _dg_native_bill_quote_origins WHERE quote_id=q.id;SELECT * INTO actual_action FROM _dg_native_dining_actions WHERE id=operation_origin.action_id;payload:=operation.request_payload::jsonb;
  IF operation_origin.operation_id IS NULL OR operation_origin.quote_id<>q.id OR q.status<>'consumed' OR operation_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR operation_origin.request_hash<>operation.request_hash OR operation.request_hash<>dg_native_office_hash(payload) OR operation_origin.created_at<>operation.created_at OR actual_action.created_at<>operation.created_at OR actual_action.kind<>'bill_confirm' OR actual_action.body_hash<>dg_native_office_hash(jsonb_build_object('quoteId',q.id,'_confirmationHash',quote_origin.confirmation_hash,'confirmed',true)) OR operation.bill_id<>q.bill_id OR operation.kind<>q.kind OR operation.parent_payment_id IS DISTINCT FROM q.parent_payment_id OR operation.amount_minor<>(q.payload::jsonb->>'amountMinor')::bigint OR operation.actor_id IS DISTINCT FROM q.actor_id OR operation.session_id IS DISTINCT FROM q.session_id OR operation.focus_version IS DISTINCT FROM q.focus_version OR operation.party_access_version<>(quote_origin.actor_meta->>'partyAccessVersion')::bigint OR operation.provider_id<>'mock-payments' OR operation.merchant_id<>q.payload::jsonb->>'merchantId' OR operation.config_version<>(q.payload::jsonb->>'configVersion')::bigint OR(operation.config_snapshot::jsonb->>'version')::bigint<>operation.config_version OR operation.config_snapshot::jsonb->>'merchant_id'<>operation.merchant_id OR operation.config_snapshot::jsonb->>'provider_id'<>operation.provider_id OR payload IS DISTINCT FROM jsonb_build_object('operationId',operation.id,'kind',operation.kind,'restaurantId',b.restaurant_id,'billId',b.id,'orderId',b.order_id,'merchantId',operation.merchant_id,'amountMinor',operation.amount_minor,'currency','CNY','parentPaymentId',operation.parent_payment_id,'parentRemoteTransactionId',(SELECT remote_transaction_id FROM restaurant_financial_operations WHERE id=operation.parent_payment_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial operations are exactly the explicitly confirmed immutable request and actor';END IF;
  IF actual_action.transaction_id=pg_current_xact_id()::text AND dg_native_bill_quote_reason(q.id,NULL,true) IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial confirmation retains actual quote, source, price and capacity until commit';END IF;
 END IF;RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_receipt_business(change_value text,event_value text,action_value text,status_value text,receipt jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;q restaurant_order_quotes%ROWTYPE;hold restaurant_inventory_reservations%ROWTYPE;line restaurant_order_lines%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;snapshot jsonb;item jsonb;created text;ticket_value text;current_total bigint;changed boolean:=false;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;snapshot:=q.payload::jsonb;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;
 IF q.id IS NULL OR o.pending_change_id IS DISTINCT FROM c.id OR o.content_version<>(snapshot->>'contentVersion')::bigint OR current_total<>(snapshot->>'oldTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_DATA_INCOMPLETE');END IF;
 IF status_value='accepted' THEN
  FOR hold IN SELECT reservation.* FROM restaurant_inventory_reservations reservation JOIN _dg_native_order_reservation_origins origin ON origin.reservation_id=reservation.id WHERE reservation.change_id=c.id AND reservation.status='reserved' ORDER BY reservation.sku_id FOR UPDATE OF reservation LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_inventory_reservations',hold.id);UPDATE restaurant_inventory_reservations SET status='committed',updated_at=created WHERE id=hold.id;
  END LOOP;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' ORDER BY value->>'lineId' LOOP
   SELECT * INTO line FROM restaurant_order_lines WHERE id=item->>'lineId' AND order_id=o.id FOR UPDATE;SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE line_id=line.id FOR UPDATE;
   IF line.id IS NULL OR ticket.id IS NULL OR ticket.pending_cancel_quantity<(item->>'quantity')::bigint OR line.quantity-line.cancelled_quantity-ticket.started_quantity<(item->>'quantity')::bigint THEN PERFORM dg_native_order_error('KITCHEN_QUANTITY_CHANGED');END IF;
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',line.id);UPDATE restaurant_order_lines SET cancelled_quantity=cancelled_quantity+(item->>'quantity')::bigint WHERE id=line.id;
   PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket.id);UPDATE restaurant_kitchen_tickets SET pending_cancel_quantity=pending_cancel_quantity-(item->>'quantity')::bigint,version=version+1,updated_at=created WHERE id=ticket.id;
  END LOOP;
  -- Return each original tracked SKU once for trusted, accepted reductions.
  FOR item IN SELECT jsonb_build_object('skuId',value->>'skuId','quantity',sum((value->>'quantity')::bigint)) FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' AND(value->>'tracked')::boolean GROUP BY value->>'skuId' ORDER BY value->>'skuId' LOOP
   PERFORM dg_native_order_stock_move(action_value,c.id,item->>'skuId',(item->>'quantity')::bigint,'cancel_return');changed:=true;
  END LOOP;
  IF changed THEN PERFORM dg_native_dining_effect(action_value,'restaurants',o.restaurant_id);UPDATE restaurants SET menu_version=menu_version+1,updated_at=created WHERE id=o.restaurant_id;END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='add' LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',item->>'lineId');INSERT INTO restaurant_order_lines(id,order_id,change_id,item_id,sku_id,item_name,sku_name,unit_price_minor,quantity,preparation_note,dietary_tags,stock_tracked,created_at) VALUES(item->>'lineId',o.id,c.id,item->>'itemId',item->>'skuId',item->>'itemName',item->>'skuName',(item->>'unitPriceMinor')::bigint,(item->>'quantity')::bigint,item->>'preparationNote',(item->'dietaryTags')::text,CASE WHEN(item->>'tracked')::boolean THEN 1 ELSE 0 END,created);
   INSERT INTO _dg_native_order_line_origins VALUES(item->>'lineId',c.id,event_value,q.id,dg_native_office_hash(item),(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
   ticket_value:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket_value);INSERT INTO restaurant_kitchen_tickets(id,restaurant_id,order_id,line_id,table_id,table_name,table_code,accepted_at,updated_at) VALUES(ticket_value,o.restaurant_id,o.id,item->>'lineId',snapshot->>'tableId',snapshot->>'tableName',snapshot->>'tableCode',created,created);INSERT INTO _dg_native_order_kitchen_origins VALUES(ticket_value,item->>'lineId',event_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
  END LOOP;
  SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;IF current_total<>(snapshot->>'newTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_AMOUNT_INVALID');END IF;
 ELSE PERFORM dg_native_order_inventory(action_value,c.id,q.id,false);END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_quotes',q.id);UPDATE restaurant_order_quotes SET status=status_value WHERE id=q.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=status_value,version=version+1,updated_at=created WHERE id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status=status_value,last_sequence=(receipt->>'sequence')::bigint,remote_request_id=receipt->>'remoteRequestId',remote_order_id=receipt->>'remoteOrderId',lease_token=NULL,lease_until=NULL,query_requested=0,error_code=CASE WHEN status_value='rejected' THEN 'POS_REJECTED' END,error_message=CASE WHEN status_value='rejected' THEN '模拟后厨明确拒绝本次变更，预占已释放。' END,version=version+1,updated_at=created WHERE change_id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET pending_change_id=NULL,content_version=content_version+CASE WHEN status_value='accepted' THEN 1 ELSE 0 END,remote_order_id=CASE WHEN status_value='accepted' THEN receipt->>'remoteOrderId' ELSE remote_order_id END,status=dg_native_order_status(o.id),attention_reason=CASE WHEN control_mode='human' THEN attention_reason END,version=version+1,updated_at=created WHERE id=o.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_pos_callbacks',event_value);UPDATE restaurant_pos_callbacks SET applied=1 WHERE event_id=event_value;PERFORM dg_native_order_event(action_value,o.id,c.id,'order_receipt',CASE WHEN status_value='accepted' THEN '模拟后厨已确认，价格快照和制作项目已持久保存，尚未结算。' ELSE '模拟后厨明确拒绝此次变更，原已接单内容保留。' END);
 PERFORM dg_native_bill_order_changed(action_value,o.id);
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;order_value text;party_value text;restaurant_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 record_value:=CASE WHEN table_value IN('restaurant_order_dispatches','mock_pos_operations') THEN j->>'change_id' WHEN table_value='restaurant_pos_callbacks' THEN j->>'event_id' ELSE j->>'id' END;
 IF table_value='restaurant_orders' THEN order_value:=j->>'id';ELSIF table_value IN('restaurant_order_changes','restaurant_order_lines','restaurant_kitchen_tickets','restaurant_order_events') THEN order_value:=j->>'order_id';ELSE SELECT order_id INTO order_value FROM restaurant_order_changes WHERE id=j->>'change_id';END IF;
 SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=party_value AND a.kind IN('order_send','order_lookup','order_unknown','order_receipt','order_query','order_mock_fixture','order_mock_remote') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch and trusted business facts cannot be deleted';END IF;
 IF table_value='restaurant_orders' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'status' NOT IN('submitting','submitted','needs_attention','accepted','draft','cancelled','preparing','ready','served','closed') OR j->>'settlement_status' IS DISTINCT FROM previous->>'settlement_status' OR(j->>'content_version')::bigint NOT BETWEEN(previous->>'content_version')::bigint AND(previous->>'content_version')::bigint+1 OR action.kind<>'order_receipt' AND j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] OR action.kind='order_receipt' AND j->>'remote_order_id' IS DISTINCT FROM previous->>'remote_order_id' AND previous->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport only changes order state or applies the original trusted content once';END IF;
 ELSIF table_value='restaurant_order_changes' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting' OR action.kind='order_lookup' AND previous->>'status'='submitting' AND j->>'status'='unknown' OR action.kind='order_unknown' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status'='unknown' OR action.kind='order_receipt' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status' IN('submitted','accepted','rejected','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport cannot rewrite draft identity, input or its original confirmation';END IF;
 ELSIF table_value='restaurant_order_dispatches' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'attempts')::bigint<>1 OR j->>'status' NOT IN('submitting','submitted','unknown','accepted','rejected') OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint OR(previous->>'attempts')::bigint=0 AND NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting') OR previous->>'status' IN('accepted','rejected') AND j->>'status' IS DISTINCT FROM previous->>'status' OR action.kind IN('order_query','order_mock_fixture') AND j-ARRAY['version','query_requested','updated_at'] IS DISTINCT FROM previous-ARRAY['version','query_requested','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts and the frozen original request cannot be reset or retargeted';END IF;
 ELSIF table_value='restaurant_order_quotes' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'current' OR j->>'status' NOT IN('accepted','rejected') OR j-'status' IS DISTINCT FROM previous-'status' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Final receipts consume the original quote without changing its deadline or contents';END IF;
 ELSIF table_value='restaurant_inventory_reservations' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'reserved' OR j->>'status' NOT IN('committed','released') OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only trusted final receipts commit or release existing reservations';END IF;
 ELSIF table_value='restaurant_stock_movements' THEN
  IF operation_value<>'INSERT' OR action.kind<>'order_receipt' OR j->>'kind' NOT IN('release','cancel_return') OR(j->>'after_quantity')::bigint<=(j->>'before_quantity')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock returns require the trusted original receipt';END IF;
 ELSIF table_value='restaurant_order_lines' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'cancelled_quantity')::bigint<>0 OR j->>'created_at'<>action.created_at) OR operation_value='UPDATE' AND(j-'cancelled_quantity' IS DISTINCT FROM previous-'cancelled_quantity' OR(j->>'cancelled_quantity')::bigint<=(previous->>'cancelled_quantity')::bigint OR(j->>'cancelled_quantity')::bigint>(j->>'quantity')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line snapshots are immutable except trusted cancelled quantities';END IF;
 ELSIF table_value='restaurant_kitchen_tickets' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'started_quantity')::bigint<>0 OR(j->>'ready_quantity')::bigint<>0 OR(j->>'served_quantity')::bigint<>0 OR(j->>'pending_cancel_quantity')::bigint<>0 OR(j->>'version')::bigint<>1 OR j->>'accepted_at'<>action.created_at) OR operation_value='UPDATE' AND(j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt creates original kitchen rows without inventing preparation progress';END IF;
 ELSIF table_value='restaurant_pos_callbacks' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND(j->>'created_at'<>action.created_at OR j->>'applied'<>'0' OR j->>'conflict'<>'0') OR operation_value='UPDATE' AND(j-ARRAY['applied','conflict'] IS DISTINCT FROM previous-ARRAY['applied','conflict'] OR previous->>'applied'<>'0' OR previous->>'conflict'<>'0' OR(j->>'applied')::bigint+(j->>'conflict')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt payload is immutable and has one terminal local application outcome';END IF;
 ELSIF table_value='mock_pos_operations' THEN
  IF operation_value<>'INSERT' OR action.kind NOT IN('order_mock_remote','order_mock_fixture') OR j->>'outcome' NOT IN('accepted','rejected') OR j->>'sequence'<>'2' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit local mock facts are append-only and cannot replace a real provider';END IF;
 ELSIF table_value='restaurant_order_events' THEN
  IF operation_value<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport audit retains its actual operation and actor';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported transport effect';END IF;RETURN true;
END;$dg$;


DO $bill_transport_acl$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema() AND p.proname LIKE 'dg_native_bill_%' LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC';END LOOP;END;$bill_transport_acl$;
